MemorySQLCipherStatus memory_sqlcipher_get_proposal_receipt(MemorySQLCipherStore *store,
                                                            const uint8_t *proposalIDBytes,
                                                            size_t proposalIDLength,
                                                            MemorySQLCipherProposalReceipt *receiptOut) {
    if (store == NULL || store->database == NULL || receiptOut == NULL
        || !valid_text_bytes(proposalIDBytes, proposalIDLength, 512)) return MemorySQLCipherStatusInvalidArgument;
    memset(receiptOut, 0, sizeof(*receiptOut));
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database,
        "SELECT owner_id,session_id,task_id,command_id,record_id,expires_at FROM owner_command_receipts WHERE proposal_id=?;",
        -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 1, (const char *)proposalIDBytes, (int)proposalIDLength, SQLITE_TRANSIENT);
    if (code == SQLITE_OK) code = sqlite3_step(statement);
    if (code == SQLITE_DONE) { sqlite3_finalize(statement); return MemorySQLCipherStatusOK; }
    if (code != SQLITE_ROW) { sqlite3_finalize(statement); return status_for_sqlite(code); }
    receiptOut->ownerID = copy_column_text(statement, 0);
    receiptOut->sessionID = copy_column_text(statement, 1);
    receiptOut->taskID = copy_column_text(statement, 2);
    receiptOut->commandKey = copy_column_text(statement, 3);
    receiptOut->recordID = copy_column_text(statement, 4);
    receiptOut->expiresAt = sqlite3_column_int64(statement, 5);
    int valid = receiptOut->ownerID && receiptOut->sessionID && receiptOut->taskID
        && receiptOut->commandKey && receiptOut->recordID
        && sqlite3_column_type(statement, 5) != SQLITE_NULL;
    sqlite3_finalize(statement);
    if (!valid) {
        memory_sqlcipher_free_proposal_receipt(receiptOut);
        return MemorySQLCipherStatusDatabaseError;
    }
    return MemorySQLCipherStatusOK;
}

void memory_sqlcipher_free_proposal_receipt(MemorySQLCipherProposalReceipt *receipt) {
    if (receipt == NULL) return;
    free(receipt->ownerID); free(receipt->sessionID); free(receipt->taskID);
    free(receipt->commandKey); free(receipt->recordID);
    memset(receipt, 0, sizeof(*receipt));
}

MemorySQLCipherStatus memory_sqlcipher_upsert_vault_display(MemorySQLCipherStore *store,
                                                            const uint8_t *handleBytes,
                                                            size_t handleLength,
                                                            const uint8_t *safeDisplayBytes,
                                                            size_t safeDisplayLength) {
    if (store == NULL || store->database == NULL
        || !valid_text_bytes(handleBytes, handleLength, 512)
        || !valid_text_bytes(safeDisplayBytes, safeDisplayLength, 512)) {
        return MemorySQLCipherStatusInvalidArgument;
    }
    static const char sql[] =
        "INSERT INTO vault_handle_displays(handle,safe_display) VALUES(?,?) "
        "ON CONFLICT(handle) DO UPDATE SET safe_display=excluded.safe_display;";
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database, sql, -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 1, (const char *)handleBytes, (int)handleLength, SQLITE_TRANSIENT);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 2, (const char *)safeDisplayBytes, (int)safeDisplayLength, SQLITE_TRANSIENT);
    if (code == SQLITE_OK) code = sqlite3_step(statement);
    if (code == SQLITE_DONE) code = SQLITE_OK;
    sqlite3_finalize(statement);
    return status_for_sqlite(code);
}

static char *copy_column_text(sqlite3_stmt *statement, int column) {
    const unsigned char *text = sqlite3_column_text(statement, column);
    int length = sqlite3_column_bytes(statement, column);
    if (text == NULL || length < 0) return NULL;
    char *copy = (char *)malloc((size_t)length + 1);
    if (copy == NULL) return NULL;
    memcpy(copy, text, (size_t)length);
    copy[length] = '\0';
    return copy;
}

static char *literal_fts_query(const uint8_t *bytes, size_t length) {
    if (!valid_text_bytes(bytes, length, 2048) || length > (SIZE_MAX - 3) / 2) return NULL;
    char *query = (char *)malloc(length * 2 + 3);
    if (query == NULL) return NULL;
    size_t output = 0;
    query[output++] = '"';
    for (size_t index = 0; index < length; index++) {
        if (bytes[index] == '"') query[output++] = '"';
        query[output++] = (char)bytes[index];
    }
    query[output++] = '"';
    query[output] = '\0';
    return query;
}

void memory_sqlcipher_free_search_rows(MemorySQLCipherSearchRow *rows, size_t count) {
    if (rows == NULL) return;
    for (size_t index = 0; index < count; index++) {
        free(rows[index].identifier);
        free(rows[index].recordType);
        free(rows[index].body);
        free(rows[index].source);
        free(rows[index].sourceMessageID);
        free(rows[index].proposalID);
        free(rows[index].statementID);
        free(rows[index].candidateOrigin);
        free(rows[index].sourceReference);
        free(rows[index].sourceSpan);
    }
    free(rows);
}

MemorySQLCipherStatus memory_sqlcipher_search(MemorySQLCipherStore *store,
                                              const uint8_t *queryBytes,
                                              size_t queryLength,
                                              int limit,
                                              MemorySQLCipherSearchRow **rowsOut,
                                              size_t *countOut) {
    if (store == NULL || store->database == NULL || queryBytes == NULL || rowsOut == NULL
        || countOut == NULL || limit < 1 || limit > 50) {
        return MemorySQLCipherStatusInvalidArgument;
    }
    if (queryLength == 0 || queryLength > 2048) {
        return MemorySQLCipherStatusInvalidArgument;
    }
    char *literalQuery = literal_fts_query(queryBytes, queryLength);
    if (literalQuery == NULL) return MemorySQLCipherStatusInvalidArgument;
    size_t literalLength = strlen(literalQuery);

    *rowsOut = NULL;
    *countOut = 0;
    static const char sql[] =
        "SELECT m.id,m.kind,m.body,m.source,m.observed_at,m.status,m.confidence,bm25(memory_fts),m.source_message_id,m.proposal_id,m.statement_id,m.candidate_origin,m.source_reference,m.source_span "
        "FROM memory_fts JOIN memory_items AS m ON m.rowid=memory_fts.rowid "
        "WHERE memory_fts MATCH ? AND m.status=1 ORDER BY bm25(memory_fts) LIMIT ?;";
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database, sql, -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 1, literalQuery,
                                                     (int)literalLength, SQLITE_TRANSIENT);
    free(literalQuery);
    if (code == SQLITE_OK) code = sqlite3_bind_int(statement, 2, limit);
    if (code != SQLITE_OK) {
        sqlite3_finalize(statement);
        return status_for_sqlite(code);
    }

    size_t capacity = 0;
    MemorySQLCipherSearchRow *rows = NULL;
    while ((code = sqlite3_step(statement)) == SQLITE_ROW) {
        if (*countOut == capacity) {
            size_t nextCapacity = capacity == 0 ? 4 : capacity * 2;
            MemorySQLCipherSearchRow *next = (MemorySQLCipherSearchRow *)realloc(rows, nextCapacity * sizeof(*rows));
            if (next == NULL) {
                memory_sqlcipher_free_search_rows(rows, *countOut);
                sqlite3_finalize(statement);
                *countOut = 0;
                return MemorySQLCipherStatusOutOfMemory;
            }
            rows = next;
            capacity = nextCapacity;
        }
        MemorySQLCipherSearchRow *row = &rows[*countOut];
        memset(row, 0, sizeof(*row));
        row->identifier = copy_column_text(statement, 0);
        row->recordType = copy_column_text(statement, 1);
        row->body = copy_column_text(statement, 2);
        row->source = copy_column_text(statement, 3);
        row->observedAt = sqlite3_column_int64(statement, 4);
        row->status = sqlite3_column_int(statement, 5);
        row->confidence = sqlite3_column_double(statement, 6);
        row->bm25Rank = sqlite3_column_double(statement, 7);
        row->sourceMessageID = sqlite3_column_type(statement, 8) == SQLITE_NULL ? NULL : copy_column_text(statement, 8);
        row->proposalID = sqlite3_column_type(statement, 9) == SQLITE_NULL ? NULL : copy_column_text(statement, 9);
        row->statementID = sqlite3_column_type(statement, 10) == SQLITE_NULL ? NULL : copy_column_text(statement, 10);
        row->candidateOrigin = sqlite3_column_type(statement, 11) == SQLITE_NULL ? NULL : copy_column_text(statement, 11);
        row->sourceReference = sqlite3_column_type(statement, 12) == SQLITE_NULL ? NULL : copy_column_text(statement, 12);
        row->sourceSpan = sqlite3_column_type(statement, 13) == SQLITE_NULL ? NULL : copy_column_text(statement, 13);
        if (row->identifier == NULL || row->recordType == NULL || row->body == NULL || row->source == NULL
            || (sqlite3_column_type(statement, 8) != SQLITE_NULL && row->sourceMessageID == NULL)
            || (sqlite3_column_type(statement, 9) != SQLITE_NULL && row->proposalID == NULL)
            || (sqlite3_column_type(statement, 10) != SQLITE_NULL && row->statementID == NULL)
            || (sqlite3_column_type(statement, 11) != SQLITE_NULL && row->candidateOrigin == NULL)
            || (sqlite3_column_type(statement, 12) != SQLITE_NULL && row->sourceReference == NULL)
            || (sqlite3_column_type(statement, 13) != SQLITE_NULL && row->sourceSpan == NULL)) {
            memory_sqlcipher_free_search_rows(rows, *countOut + 1);
            sqlite3_finalize(statement);
            *countOut = 0;
            return MemorySQLCipherStatusOutOfMemory;
        }
        (*countOut)++;
    }
    sqlite3_finalize(statement);
    if (code != SQLITE_DONE) {
        memory_sqlcipher_free_search_rows(rows, *countOut);
        *countOut = 0;
        return status_for_sqlite(code);
    }
    *rowsOut = rows;
    return MemorySQLCipherStatusOK;
}

static int fill_record_row(sqlite3_stmt *statement, MemorySQLCipherSearchRow *row) {
    memset(row, 0, sizeof(*row));
    row->identifier = copy_column_text(statement, 0);
    row->recordType = copy_column_text(statement, 1);
    row->body = copy_column_text(statement, 2);
    row->source = copy_column_text(statement, 3);
    row->observedAt = sqlite3_column_int64(statement, 4);
    row->status = sqlite3_column_int(statement, 5);
    row->confidence = sqlite3_column_double(statement, 6);
    row->sourceMessageID = sqlite3_column_type(statement, 7) == SQLITE_NULL ? NULL : copy_column_text(statement, 7);
    row->proposalID = sqlite3_column_type(statement, 8) == SQLITE_NULL ? NULL : copy_column_text(statement, 8);
    row->statementID = sqlite3_column_type(statement, 9) == SQLITE_NULL ? NULL : copy_column_text(statement, 9);
    row->candidateOrigin = sqlite3_column_type(statement, 10) == SQLITE_NULL ? NULL : copy_column_text(statement, 10);
    row->sourceReference = sqlite3_column_type(statement, 11) == SQLITE_NULL ? NULL : copy_column_text(statement, 11);
    row->sourceSpan = sqlite3_column_type(statement, 12) == SQLITE_NULL ? NULL : copy_column_text(statement, 12);
    return row->identifier && row->recordType && row->body && row->source
        && (sqlite3_column_type(statement, 7) == SQLITE_NULL || row->sourceMessageID)
        && (sqlite3_column_type(statement, 8) == SQLITE_NULL || row->proposalID)
        && (sqlite3_column_type(statement, 9) == SQLITE_NULL || row->statementID)
        && (sqlite3_column_type(statement, 10) == SQLITE_NULL || row->candidateOrigin)
        && (sqlite3_column_type(statement, 11) == SQLITE_NULL || row->sourceReference)
        && (sqlite3_column_type(statement, 12) == SQLITE_NULL || row->sourceSpan);
}

MemorySQLCipherStatus memory_sqlcipher_get(MemorySQLCipherStore *store,
                                           const uint8_t *identifierBytes,
                                           size_t identifierLength,
                                           MemorySQLCipherSearchRow **rowOut) {
    if (store == NULL || store->database == NULL || rowOut == NULL
        || !valid_text_bytes(identifierBytes, identifierLength, 512)) return MemorySQLCipherStatusInvalidArgument;
    *rowOut = NULL;
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database,
        "SELECT id,kind,body,source,observed_at,status,confidence,source_message_id,proposal_id,statement_id,candidate_origin,source_reference,source_span FROM memory_items WHERE id=?;", -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 1, (const char *)identifierBytes, (int)identifierLength, SQLITE_TRANSIENT);
    if (code == SQLITE_OK) code = sqlite3_step(statement);
    if (code == SQLITE_DONE) { sqlite3_finalize(statement); return MemorySQLCipherStatusOK; }
    if (code != SQLITE_ROW) { sqlite3_finalize(statement); return status_for_sqlite(code); }
    MemorySQLCipherSearchRow *row = calloc(1, sizeof(*row));
    if (row == NULL || !fill_record_row(statement, row)) {
        if (row) { memory_sqlcipher_free_search_rows(row, 1); }
        sqlite3_finalize(statement); return MemorySQLCipherStatusOutOfMemory;
    }
    sqlite3_finalize(statement); *rowOut = row; return MemorySQLCipherStatusOK;
}

MemorySQLCipherStatus memory_sqlcipher_list(MemorySQLCipherStore *store, int includeInactive,
                                            int limit, MemorySQLCipherSearchRow **rowsOut,
                                            size_t *countOut) {
    if (store == NULL || store->database == NULL || rowsOut == NULL || countOut == NULL
        || (includeInactive != 0 && includeInactive != 1) || limit < 1 || limit > 500) return MemorySQLCipherStatusInvalidArgument;
    *rowsOut = NULL; *countOut = 0;
    const char *sql = includeInactive
        ? "SELECT id,kind,body,source,observed_at,status,confidence,source_message_id,proposal_id,statement_id,candidate_origin,source_reference,source_span FROM memory_items ORDER BY observed_at DESC,id LIMIT ?;"
        : "SELECT id,kind,body,source,observed_at,status,confidence,source_message_id,proposal_id,statement_id,candidate_origin,source_reference,source_span FROM memory_items WHERE status=1 ORDER BY observed_at DESC,id LIMIT ?;";
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database, sql, -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_int(statement, 1, limit);
    if (code != SQLITE_OK) {
        sqlite3_finalize(statement);
        return status_for_sqlite(code);
    }
    MemorySQLCipherSearchRow *rows = calloc((size_t)limit, sizeof(*rows));
    if (rows == NULL) { sqlite3_finalize(statement); return MemorySQLCipherStatusOutOfMemory; }
    size_t count = 0;
    while ((code = sqlite3_step(statement)) == SQLITE_ROW) {
        if (count >= (size_t)limit) { code = SQLITE_TOOBIG; break; }
        if (!fill_record_row(statement, &rows[count])) { code = SQLITE_NOMEM; break; }
        count++;
    }
    sqlite3_finalize(statement);
    if (code != SQLITE_DONE) { memory_sqlcipher_free_search_rows(rows, count + (count < (size_t)limit ? 1 : 0)); return status_for_sqlite(code); }
    *rowsOut = rows; *countOut = count; return MemorySQLCipherStatusOK;
}

MemorySQLCipherStatus memory_sqlcipher_owner_page(MemorySQLCipherStore *store,
    const uint8_t *queryBytes, size_t queryLength, const uint8_t *afterBytes,
    size_t afterLength, int limit, MemorySQLCipherSearchRow **rowsOut, size_t *countOut) {
    if (store == NULL || store->database == NULL || rowsOut == NULL || countOut == NULL || limit < 1 || limit > 33
        || (queryBytes == NULL) != (queryLength == 0) || (afterBytes == NULL) != (afterLength == 0)
        || (queryBytes && !valid_text_bytes(queryBytes, queryLength, 2048))
        || (afterBytes && !valid_text_bytes(afterBytes, afterLength, 512))) return MemorySQLCipherStatusInvalidArgument;
    *rowsOut = NULL; *countOut = 0;
    char *literal = queryBytes ? literal_fts_query(queryBytes, queryLength) : NULL;
    if (queryBytes && literal == NULL) return MemorySQLCipherStatusInvalidArgument;
    char sql[512];
    const char *join = queryBytes ? " JOIN memory_fts ON memory_fts.rowid=m.rowid" : "";
    int written = snprintf(sql, sizeof(sql),
        "SELECT m.id,m.kind,m.body,m.source,m.observed_at,m.status,m.confidence,m.source_message_id,m.proposal_id,m.statement_id,m.candidate_origin,m.source_reference,m.source_span FROM memory_items AS m%s WHERE m.kind IN ('profile','fact')%s%s ORDER BY m.id COLLATE BINARY LIMIT ?;",
        join, queryBytes ? " AND memory_fts MATCH ?" : "", afterBytes ? " AND m.id COLLATE BINARY > ?" : "");
    if (written < 0 || (size_t)written >= sizeof(sql)) { free(literal); return MemorySQLCipherStatusDatabaseError; }
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database, sql, -1, &statement, NULL);
    int bind = 1;
    if (code == SQLITE_OK && queryBytes) code = sqlite3_bind_text(statement, bind++, literal, (int)strlen(literal), SQLITE_TRANSIENT);
    if (code == SQLITE_OK && afterBytes) code = sqlite3_bind_text(statement, bind++, (const char *)afterBytes, (int)afterLength, SQLITE_TRANSIENT);
    free(literal);
    if (code == SQLITE_OK) code = sqlite3_bind_int(statement, bind, limit);
    if (code != SQLITE_OK) { sqlite3_finalize(statement); return status_for_sqlite(code); }
    MemorySQLCipherSearchRow *rows = calloc((size_t)limit, sizeof(*rows));
    if (rows == NULL) { sqlite3_finalize(statement); return MemorySQLCipherStatusOutOfMemory; }
    size_t count = 0;
    while ((code = sqlite3_step(statement)) == SQLITE_ROW) {
        if (count >= (size_t)limit || !fill_record_row(statement, &rows[count])) { code = SQLITE_NOMEM; break; }
        count++;
    }
    sqlite3_finalize(statement);
    if (code != SQLITE_DONE) {
        memory_sqlcipher_free_search_rows(rows, count + (count < (size_t)limit ? 1 : 0));
        return status_for_sqlite(code);
    }
    *rowsOut = rows; *countOut = count;
    return MemorySQLCipherStatusOK;
}

MemorySQLCipherStatus memory_sqlcipher_delete(MemorySQLCipherStore *store,
                                              const uint8_t *identifierBytes,
                                              size_t identifierLength) {
    if (store == NULL || store->database == NULL
        || !valid_text_bytes(identifierBytes, identifierLength, 512)) return MemorySQLCipherStatusInvalidArgument;
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database, "DELETE FROM memory_items WHERE id=?;", -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 1, (const char *)identifierBytes,
                                                    (int)identifierLength, SQLITE_TRANSIENT);
    if (code == SQLITE_OK) code = sqlite3_step(statement);
    if (code == SQLITE_DONE) code = SQLITE_OK;
    sqlite3_finalize(statement);
    return status_for_sqlite(code);
}

MemorySQLCipherStatus memory_sqlcipher_update_status(MemorySQLCipherStore *store,
                                                     const uint8_t *identifierBytes,
                                                     size_t identifierLength,
                                                     int active) {
    if (store == NULL || store->database == NULL || active < 0 || active > 1
        || !valid_text_bytes(identifierBytes, identifierLength, 512)) return MemorySQLCipherStatusInvalidArgument;
    sqlite3_stmt *statement = NULL;
    int code = sqlite3_prepare_v2(store->database, "UPDATE memory_items SET status=? WHERE id=?;", -1, &statement, NULL);
    if (code == SQLITE_OK) code = sqlite3_bind_int(statement, 1, active);
    if (code == SQLITE_OK) code = sqlite3_bind_text(statement, 2, (const char *)identifierBytes, (int)identifierLength, SQLITE_TRANSIENT);
    if (code == SQLITE_OK) code = sqlite3_step(statement);
    if (code == SQLITE_DONE) code = SQLITE_OK;
    sqlite3_finalize(statement);
    return status_for_sqlite(code);
}

MemorySQLCipherStatus memory_sqlcipher_checkpoint(MemorySQLCipherStore *store) {
    if (store == NULL || store->database == NULL) return MemorySQLCipherStatusInvalidArgument;
    int logFrames = 0;
    int checkpointedFrames = 0;
    int code = sqlite3_wal_checkpoint_v2(store->database, NULL, SQLITE_CHECKPOINT_TRUNCATE,
                                         &logFrames, &checkpointedFrames);
    return status_for_sqlite(code);
}

MemorySQLCipherStatus memory_sqlcipher_close(MemorySQLCipherStore **store) {
    if (store == NULL || *store == NULL) return MemorySQLCipherStatusOK;
    int code = sqlite3_close_v2((*store)->database);
    if (code != SQLITE_OK) return status_for_sqlite(code);
    free(*store);
    *store = NULL;
    return MemorySQLCipherStatusOK;
}
